"""Build the demo warehouse: TPC-DS, generated by DuckDB's own tpcds extension.

    python seed_warehouse.py /warehouse/tpcds.duckdb [scale factor]

Scale factor 0.1 is about 290 thousand store sales rows and a 60 MB file,
generated in a few seconds. Nothing is downloaded but the extension.
"""

import os
import sys

import duckdb

path = sys.argv[1]
scale = float(sys.argv[2]) if len(sys.argv) > 2 else 0.1

if os.path.exists(path):
    print(f"{path} exists, keeping it")
    sys.exit(0)

con = duckdb.connect(path)
con.execute("INSTALL tpcds; LOAD tpcds")
con.execute(f"CALL dsdgen(sf={scale})")
rows = con.execute("SELECT count(*) FROM store_sales").fetchone()[0]
con.close()
print(f"{path}: TPC-DS at scale {scale}, {rows:,} store sales rows")
